<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Balloon Archer 95</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  html,body{margin:0;height:100%;background:#008080;display:flex;align-items:center;justify-content:center;font-family:'Press Start 2P',monospace;overflow:auto}
  .win{background:#c0c0c0;border:2px solid;border-color:#dfdfdf #404040 #404040 #dfdfdf;box-shadow:2px 2px 0 #000,5px 5px 0 rgba(0,0,0,.35);margin:10px}
  .titlebar{background:linear-gradient(90deg,#000080,#1084d0);color:#fff;font-size:11px;padding:5px 8px;display:flex;gap:8px;align-items:center;user-select:none}
  .titlebar .btns{margin-left:auto;display:flex;gap:2px}
  .titlebar .b{width:18px;height:15px;background:#c0c0c0;border:1px solid;border-color:#fff #404040 #404040 #fff;font-size:8px;line-height:13px;text-align:center;color:#000}
  .hud{display:flex;gap:6px;padding:6px;align-items:center;flex-wrap:wrap}
  .panel{background:#c0c0c0;border:2px solid;border-color:#808080 #fff #fff #808080;padding:6px 10px;font-size:9px;color:#000;display:flex;gap:8px;align-items:center}
  .panel b{color:#000080;font-weight:normal}
  #livesEl{color:#d00000;letter-spacing:2px}
  #cv{display:block;width:100%;cursor:crosshair}
  .wrap{position:relative}
  .overlay{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;background:rgba(0,0,50,.55);color:#fff;text-align:center}
  .overlay h1{font-size:30px;margin:0;text-shadow:4px 4px 0 #000;line-height:1.4}
  .overlay p{font-size:9px;line-height:2.4;margin:0}
  button{font-family:inherit;font-size:12px;background:#c0c0c0;border:2px solid;border-color:#fff #404040 #404040 #fff;padding:12px 24px;cursor:pointer;box-shadow:2px 2px 0 #000;color:#000}
  button:active{border-color:#404040 #fff #fff #404040;box-shadow:none;transform:translate(1px,1px)}
  .hidden{display:none!important}
</style>
</head>
<body>
<div class="win">
  <div class="titlebar"><span>ARCHER 95 - Level 1</span><span class="btns"><span class="b">_</span><span class="b">[]</span><span class="b">x</span></span></div>
  <div class="hud">
    <div class="panel">SCORE <b id="score">000</b>/100</div>
    <div class="panel">LIVES <b id="livesEl">&#9829;&#9829;&#9829;</b></div>
    <div class="panel">POWER <b id="pow">--</b></div>
    <div class="panel" style="margin-left:auto">HOLD MOUSE: DRAW &nbsp; RELEASE: SHOOT</div>
  </div>
  <div class="wrap">
    <canvas id="cv" width="960" height="540"></canvas>
    <div id="ovStart" class="overlay">
      <h1>BALLOON<br>ARCHER 95</h1>
      <p>AIM WITH THE MOUSE<br>HOLD THE MOUSE BUTTON TO DRAW THE BOW<br>RELEASE TO SHOOT - MORE PULL, FASTER ARROW<br>POP 100 POINTS BEFORE 3 BALLOONS ESCAPE</p>
      <button id="btnStart">START</button>
    </div>
    <div id="ovOver" class="overlay hidden">
      <h1>GAME OVER</h1>
      <p id="ovScore">SCORE 000</p>
      <button class="again">TRY AGAIN</button>
    </div>
    <div id="ovWin" class="overlay hidden">
      <h1>LEVEL 1<br>COMPLETE!</h1>
      <p id="winScore">SCORE 100</p>
      <button class="again">PLAY AGAIN</button>
    </div>
  </div>
</div>
<script>
'use strict';
const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
const W=960,H=540,GROUND=H-44,G=380,TARGET=100;
const $=id=>document.getElementById(id);
const scoreEl=$('score'),livesEl=$('livesEl'),powEl=$('pow');
const ovStart=$('ovStart'),ovOver=$('ovOver'),ovWin=$('ovWin');

/* ---------- audio (Web Audio, no files) ---------- */
let AC=null,master;
function audio(){
  if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain();master.gain.value=.5;master.connect(AC.destination);}
  if(AC.state==='suspended')AC.resume();
  return AC;
}
